-- These are demonstration profiles, not verified accounts of the named retailers.
INSERT INTO "user" (email, password_hash)
SELECT 'seed.market-seller.' || lpad(n::text, 3, '0') || '@example.test',
       '$2a$10$N9qo8uLOickgx2ZMRZoMyeIjZAgcfl7p92ldGxad68LJZdL17lhWy'
FROM generate_series(1, 80) AS n;

INSERT INTO seller (user_id, name, description, avatar_url)
SELECT u.id, names.name, 'Демонстрационный профиль продавца.',
       CASE names.n
           WHEN 1 THEN '/media/seed-sellers/001-dns.png'
           WHEN 17 THEN '/media/seed-sellers/017-ikea.png'
           WHEN 26 THEN '/media/seed-sellers/026-adidas.png'
           WHEN 36 THEN '/media/seed-sellers/036-lego.png'
           ELSE '/media/categories/4/category.webp'
       END
FROM unnest(ARRAY[
    'DNS', 'М.Видео', 'Эльдорадо', 'Ситилинк', 'Ozon', 'Wildberries', 'Яндекс Маркет', 'Лемана ПРО', 'Петрович', 'ВсеИнструменты.ру',
    'Hoff', 'Аскона', 'Диван.ру', 'Столплит', 'Лазурит', 'Шатура', 'IKEA', 'Castorama', 'Obi', 'Leroy Merlin',
    'Спортмастер', 'Декатлон', 'СпортКульт', 'Кант', 'Триал-Спорт', 'Adidas', 'Nike', 'Puma', 'Reebok', 'New Balance',
    'Детский мир', 'Кораблик', 'Дочки-Сыночки', 'Акушерство', 'Mothercare', 'LEGO', 'Hamleys', 'Читай-город', 'Буквоед', 'Республика',
    'Лабиринт', 'ЛитРес', 'Золотое Яблоко', 'Л''Этуаль', 'Рив Гош', 'Подружка', 'Магнит Косметик', 'Иль де Ботэ', 'Yves Rocher', 'Sephora',
    'Лента', 'Магнит', 'Пятёрочка', 'Перекрёсток', 'Ашан', 'ВкусВилл', 'Метро', 'Глобус', 'О''КЕЙ', 'Дикси',
    'Самокат', 'Купер', 'Утконос', 'Азбука Вкуса', 'Мираторг', 'Красное и Белое', 'Бристоль', 'Бетховен', 'Четыре Лапы', 'Зоозавр',
    'Ле''Муррр', 'Petshop.ru', 'Заповедник', 'Мокрый нос', 'Связной', 'МТС', 'МегаФон', 'Билайн', 'Tele2', 're:Store'
]) WITH ORDINALITY AS names(name, n)
JOIN "user" AS u ON u.email = 'seed.market-seller.' || lpad(names.n::text, 3, '0') || '@example.test';

-- Every tenth listing uses one of two source products with three photographs.
WITH listings AS (
    SELECT n,
           CASE WHEN n <= 520 THEN (n - 1) / 13 + 1 ELSE (n - 521) / 12 + 41 END AS seller_number,
           CASE WHEN n <= 520 THEN (n - 1) % 13 + 1 ELSE (n - 521) % 12 + 1 END AS slot
    FROM generate_series(1, 850) AS n
), sources AS (
    SELECT *, CASE WHEN n % 10 = 0 THEN
               CASE WHEN (n / 10) % 2 = 0 THEN 29 ELSE 30 END
           ELSE
               (ARRAY[31, 2, 3, 4, 5, 6, 7, 8, 9, 24, 32, 33, 34])
               [slot - (n / 10 - (n - slot) / 10)]
           END AS source_id
    FROM listings
), inserted AS (
    INSERT INTO product (category_id, seller_id, price, discount, name, description, available_count, created_at, updated_at)
    SELECT source.category_id, u.id, source.price + sources.seller_number, source.discount, source.name,
           source.description, source.available_count,
           '2025-01-01 12:00:00+00'::timestamptz + sources.n * interval '8 hours',
           '2025-01-01 12:00:00+00'::timestamptz + sources.n * interval '8 hours'
    FROM sources
    JOIN "user" AS u ON u.email = 'seed.market-seller.' || lpad(sources.seller_number::text, 3, '0') || '@example.test'
    JOIN product AS source ON source.id = sources.source_id
    RETURNING id, seller_id, name
)
INSERT INTO product_picture (product_id, picture_url)
SELECT inserted.id, picture.picture_url
FROM inserted
JOIN product AS source ON source.name = inserted.name AND source.id IN (2, 3, 4, 5, 6, 7, 8, 9, 24, 29, 30, 31, 32, 33, 34)
JOIN product_picture AS picture ON picture.product_id = source.id;

-- Price is in kopecks at 100 RUB/USD; discount is rounded to whole percent.
-- Local picture URLs refer to db/media; duplicate image bytes are excluded.
WITH catalog (seq, name, category, description, price, discount, stock, picture_urls) AS (
     VALUES
     (1, 'Тушь Essence Lash Princess для ресниц', 'Косметика', 'Тушь Essence Lash Princess предназначена для макияжа ресниц. Она помогает придать им объём и визуально удлинить их. Средство используют для выразительного акцента на глазах.', 99900, 10, 99, ARRAY['/media/dummyjson-products/1/1.webp']::text[]),
     (2, 'Палетка теней с зеркалом', 'Косметика', 'Палетка теней позволяет сочетать оттенки в макияже глаз. Встроенное зеркало пригодится при нанесении и поправлении макияжа. С её помощью можно создавать как сдержанные, так и более заметные сочетания цветов.', 199900, 18, 34, ARRAY['/media/dummyjson-products/2/1.webp']::text[]),
     (3, 'Пудра в баночке', 'Косметика', 'Пудра Powder Canister предназначена для закрепления макияжа. Мелкий помол помогает получить ровное матовое покрытие. Её наносят, чтобы уменьшить заметность блеска кожи.', 149900, 10, 89, ARRAY['/media/dummyjson-products/3/1.webp']::text[]),
     (4, 'Красная помада', 'Косметика', 'Красная помада придаёт губам насыщенный цвет. Кремовая текстура облегчает нанесение средства. Такой оттенок можно использовать как самостоятельный акцент в макияже.', 129900, 12, 91, ARRAY['/media/dummyjson-products/4/1.webp']::text[]),
     (5, 'Calvin Klein CK One', 'Парфюмерия', 'Calvin Klein CK One — аромат для женщин и мужчин. Композиция сочетает цитрусовые, цветочные и древесные ноты. Парфюм можно наносить как дополнение к повседневному образу.', 499900, 2, 29, ARRAY['/media/dummyjson-products/6/1.webp', '/media/dummyjson-products/6/2.webp', '/media/dummyjson-products/6/3.webp']::text[]),
     (6, 'Красный лак для ногтей', 'Косметика', 'Красный лак предназначен для декоративного покрытия ногтей. Глянцевый цвет подходит для однотонного маникюра или акцентов. После нанесения покрытию нужно дать высохнуть.', 89900, 11, 79, ARRAY['/media/dummyjson-products/5/1.webp']::text[]),
     (7, 'Яблоко', 'Продукты питания', 'Яблоко можно съесть отдельно или добавить во фруктовый салат. Нарезанные кусочки также подходят для выпечки и каши. Перед употреблением фрукт следует вымыть.', 19900, 13, 8, ARRAY['/media/dummyjson-products/16/1.webp']::text[]),
     (8, 'Говяжий стейк', 'Продукты питания', 'Говяжий стейк предназначен для приготовления горячего блюда. Его можно обжарить или приготовить на гриле. К мясу подают овощи, соус или другой гарнир.', 129900, 10, 86, ARRAY['/media/dummyjson-products/17/1.webp']::text[]),
     (9, 'Корм для кошек', 'Товары для животных', 'Корм предназначен для питания кошек. Порцию следует подбирать с учётом потребностей животного и рекомендаций производителя. Состав и правила хранения указаны на упаковке.', 89900, 10, 46, ARRAY['/media/dummyjson-products/18/1.webp']::text[]),
     (10, 'Chanel Coco Noir', 'Парфюмерия', 'Chanel Coco Noir — парфюмерная композиция для завершения образа. В аромате сочетаются цветочные, древесные и пряные ноты. Парфюм наносят на кожу в небольшом количестве.', 1299900, 17, 58, ARRAY['/media/dummyjson-products/7/1.webp', '/media/dummyjson-products/7/2.webp', '/media/dummyjson-products/7/3.webp']::text[]),
     (11, 'Куриное мясо', 'Продукты питания', 'Куриное мясо используют для приготовления основных блюд и супов. Его можно запекать, тушить или обжаривать. Перед подачей мясо необходимо полностью приготовить.', 99900, 14, 97, ARRAY['/media/dummyjson-products/19/1.webp', '/media/dummyjson-products/19/2.webp']::text[]),
     (12, 'Кулинарное масло', 'Продукты питания', 'Кулинарное масло используют при приготовлении пищи. Его можно добавлять в блюда или применять при жарке с учётом указаний на упаковке. Вид масла и условия хранения следует уточнить по этикетке.', 49900, 9, 10, ARRAY['/media/dummyjson-products/20/1.webp']::text[]),
     (13, 'Огурец', 'Продукты питания', 'Огурец подходит для овощных салатов и холодных закусок. Его также можно нарезать к основному блюду или положить в бутерброд. Перед приготовлением овощ следует вымыть.', 14900, 0, 84, ARRAY['/media/dummyjson-products/21/1.webp']::text[]),
     (14, 'Корм для собак', 'Продукты питания', 'Корм предназначен для собак. При выборе порции учитывают возраст и потребности питомца. Состав и рекомендации по кормлению приведены на упаковке.', 109900, 10, 71, ARRAY['/media/dummyjson-products/22/1.webp']::text[]),
     (15, 'Dior J''adore', 'Парфюмерия', 'Dior J''adore — цветочный парфюм. Его композиция объединяет ноты жасмина, розы и иланг-иланга. Аромат можно использовать как завершающий штрих образа.', 899900, 15, 98, ARRAY['/media/dummyjson-products/8/1.webp', '/media/dummyjson-products/8/2.webp', '/media/dummyjson-products/8/3.webp']::text[]),
     (16, 'Яйца', 'Продукты питания', 'Яйца используют для завтраков, выпечки и других блюд. Их можно сварить или добавить в тесто. Хранить и готовить продукт следует с соблюдением рекомендаций на упаковке.', 29900, 11, 9, ARRAY['/media/dummyjson-products/23/1.webp']::text[]),
     (17, 'Рыбный стейк', 'Продукты питания', 'Рыбный стейк предназначен для приготовления горячего блюда. Его можно запечь или обжарить. В качестве гарнира подойдут овощи или рис.', 149900, 4, 74, ARRAY['/media/dummyjson-products/24/1.webp']::text[]),
     (18, 'Зелёный сладкий перец', 'Продукты питания', 'Зелёный сладкий перец добавляют в салаты и горячие блюда. Его можно нарезать для закуски или использовать для фарширования. Перед приготовлением перец моют и очищают от семян.', 12900, 0, 33, ARRAY['/media/dummyjson-products/25/1.webp']::text[]),
     (19, 'Зелёный перец чили', 'Продукты питания', 'Зелёный перец чили используют для придания блюдам остроты. Его можно нарезать в соус, суп или овощную смесь. Количество перца выбирают по желаемой остроте.', 9900, 1, 3, ARRAY['/media/dummyjson-products/26/1.webp']::text[]),
     (20, 'Dolce Shine', 'Парфюмерия', 'Dolce Shine — парфюмерная композиция Dolce & Gabbana. В её аромате сочетаются фруктовые и цветочные ноты. Парфюм дополняет образ и раскрывается на коже индивидуально.', 699900, 1, 4, ARRAY['/media/dummyjson-products/9/1.webp', '/media/dummyjson-products/9/2.webp', '/media/dummyjson-products/9/3.webp']::text[]),
     (21, 'Мёд в банке', 'Продукты питания', 'Мёд в банке можно добавлять в чай или намазывать на хлеб. Он также подходит для приготовления десертов и соусов. Условия хранения и состав следует проверить на этикетке.', 69900, 14, 34, ARRAY['/media/dummyjson-products/27/1.webp']::text[]),
     (22, 'Сок', 'Продукты питания', 'Сок можно подать как самостоятельный напиток или дополнить им завтрак. Его также используют в составе безалкогольных коктейлей. Вид сока и состав указаны на упаковке.', 39900, 12, 50, ARRAY['/media/dummyjson-products/29/1.webp']::text[]),
     (23, 'Киви', 'Продукты питания', 'Киви можно очистить и съесть отдельно. Нарезанный фрукт добавляют в салаты, йогурт или десерты. Перед очисткой его следует вымыть.', 24900, 15, 99, ARRAY['/media/dummyjson-products/30/1.webp']::text[]),
     (24, 'Лимон', 'Продукты питания', 'Лимон добавляют в чай, соусы и выпечку. Его сок придаёт блюдам кислый вкус. Цедру вымытого плода можно использовать в рецептах.', 7900, 10, 31, ARRAY['/media/dummyjson-products/31/1.webp']::text[]),
     (25, 'Gucci Bloom', 'Парфюмерия', 'Gucci Bloom — парфюм с цветочным характером. Композиция включает ноты жасмина и туберозы. Аромат можно использовать для завершения личного образа.', 799900, 14, 91, ARRAY['/media/dummyjson-products/10/1.webp', '/media/dummyjson-products/10/2.webp', '/media/dummyjson-products/10/3.webp']::text[]),
     (26, 'Молоко', 'Продукты питания', 'Молоко можно пить отдельно или добавлять в кофе и чай. Его используют для каш, соусов и выпечки. После открытия упаковку следует хранить согласно маркировке.', 34900, 14, 27, ARRAY['/media/dummyjson-products/32/1.webp']::text[]),
     (27, 'Шелковица', 'Продукты питания', 'Шелковицу можно есть отдельно или добавлять в десерты. Ягоды подходят для каши и фруктовых салатов. Перед употреблением их следует промыть.', 49900, 13, 99, ARRAY['/media/dummyjson-products/33/1.webp']::text[]),
     (28, 'Кофе Nescafe', 'Продукты питания', 'Кофе Nescafe предназначен для приготовления кофейного напитка. Его можно подать самостоятельно или дополнить молоком. Способ приготовления указан на упаковке.', 79900, 2, 57, ARRAY['/media/dummyjson-products/34/1.webp']::text[]),
     (29, 'Картофель', 'Продукты питания', 'Картофель используют для супов, гарниров и запеканок. Его можно отварить, запечь или обжарить. Перед приготовлением клубни следует вымыть и при необходимости очистить.', 22900, 5, 13, ARRAY['/media/dummyjson-products/35/1.webp']::text[]),
     (30, 'Кровать Annibale Colombo', 'Мебель', 'Кровать Annibale Colombo предназначена для обустройства спального места. Она служит основой для размещения матраса. Перед заказом стоит сверить размеры кровати и подходящего матраса.', 18999900, 9, 88, ARRAY['/media/dummyjson-products/11/1.webp', '/media/dummyjson-products/11/2.webp', '/media/dummyjson-products/11/3.webp']::text[]),
     (31, 'Протеиновый порошок', 'Продукты питания', 'Протеиновый порошок предназначен для приготовления белкового напитка. Его можно смешивать согласно инструкции производителя. Состав и рекомендуемую порцию следует проверить на упаковке.', 199900, 8, 80, ARRAY['/media/dummyjson-products/36/1.webp']::text[]),
     (32, 'Красный лук', 'Продукты питания', 'Красный лук добавляют в салаты, маринады и горячие блюда. Его можно использовать сырым или подвергать тепловой обработке. Перед нарезкой луковицу очищают от шелухи.', 19900, 10, 82, ARRAY['/media/dummyjson-products/37/1.webp']::text[]),
     (33, 'Рис', 'Продукты питания', 'Рис используют для гарниров, супов и других блюд. Перед приготовлением его можно промыть. Время варки и пропорции воды следует сверить с упаковкой.', 59900, 9, 59, ARRAY['/media/dummyjson-products/38/1.webp']::text[]),
     (34, 'Безалкогольный напиток', 'Продукты питания', 'Безалкогольный напиток можно подать к еде или отдельно. Он также может стать основой для смешанного напитка. Вкус и состав следует уточнить по этикетке.', 19900, 17, 53, ARRAY['/media/dummyjson-products/39/1.webp']::text[]),
     (35, 'Диван Annibale Colombo', 'Мебель', 'Диван Annibale Colombo предназначен для сидения и отдыха. Его можно разместить в гостиной или зоне общения. Перед покупкой проверьте габариты и место для установки.', 24999900, 14, 60, ARRAY['/media/dummyjson-products/12/1.webp', '/media/dummyjson-products/12/2.webp', '/media/dummyjson-products/12/3.webp']::text[]),
     (36, 'Клубника', 'Продукты питания', 'Клубнику можно подать как самостоятельный десерт. Ягоды также добавляют в выпечку, йогурт или фруктовый салат. Перед едой их следует вымыть и удалить плодоножки.', 39900, 1, 46, ARRAY['/media/dummyjson-products/40/1.webp']::text[]),
     (37, 'Бумажные салфетки в коробке', 'Продукты питания', 'Бумажные салфетки в коробке пригодятся дома или на рабочем столе. Их используют для повседневных гигиенических нужд. Коробка позволяет доставать салфетки по мере необходимости.', 24900, 13, 86, ARRAY['/media/dummyjson-products/41/1.webp', '/media/dummyjson-products/41/2.webp']::text[]),
     (38, 'Вода', 'Продукты питания', 'Воду можно пить самостоятельно или подавать к еде. Она также используется для приготовления напитков. Тип воды и условия хранения указаны на этикетке.', 9900, 15, 53, ARRAY['/media/dummyjson-products/42/1.webp']::text[]),
     (39, 'Фоторамка «Семейное дерево»', 'Товары для дома', 'Фоторамка в виде семейного дерева предназначена для размещения снимков. Она помогает собрать изображения близких в одной композиции. Рамку можно использовать как украшение интерьера.', 299900, 15, 77, ARRAY['/media/dummyjson-products/44/1.webp']::text[]),
     (40, 'Прикроватная тумба African Cherry', 'Мебель', 'Прикроватная тумба African Cherry размещается рядом с кроватью. На неё можно положить книгу или поставить ночной светильник. Перед покупкой стоит сверить её размеры с доступным пространством.', 2999900, 19, 64, ARRAY['/media/dummyjson-products/13/1.webp', '/media/dummyjson-products/13/2.webp', '/media/dummyjson-products/13/3.webp']::text[]),
     (41, 'Настольная лампа', 'Товары для дома', 'Настольная лампа предназначена для локального освещения. Её можно поставить на рабочий стол или рядом с кроватью. Подходящий источник света и условия подключения следует уточнить для этой модели.', 499900, 7, 9, ARRAY['/media/dummyjson-products/47/1.webp']::text[]),
     (42, 'Бамбуковая лопатка', 'Товары для дома', 'Бамбуковая лопатка используется при приготовлении пищи. Ею можно перемешивать или перекладывать ингредиенты. После использования кухонную утварь следует очистить.', 79900, 3, 37, ARRAY['/media/dummyjson-products/48/1.webp']::text[]),
     (43, 'Чёрная алюминиевая чашка', 'Товары для дома', 'Чёрная алюминиевая чашка предназначена для напитков. Её можно использовать при сервировке стола. Рекомендации по мытью и допустимым напиткам стоит уточнить у продавца.', 59900, 16, 75, ARRAY['/media/dummyjson-products/49/1.webp', '/media/dummyjson-products/49/2.webp']::text[]),
     (44, 'Чёрный венчик', 'Товары для дома', 'Чёрный венчик используют для смешивания и взбивания ингредиентов. Им можно размешивать яйца, соусы или жидкое тесто. После приготовления венчик необходимо вымыть.', 99900, 10, 73, ARRAY['/media/dummyjson-products/50/1.webp']::text[]),
     (45, 'Кресло для конференций Knoll Saarinen Executive', 'Мебель', 'Кресло Knoll Saarinen Executive предназначено для конференц-зоны. Оно подходит для размещения за столом переговоров. Перед выбором стоит сопоставить размеры кресла с высотой стола.', 4999900, 2, 26, ARRAY['/media/dummyjson-products/14/1.webp', '/media/dummyjson-products/14/2.webp', '/media/dummyjson-products/14/3.webp']::text[]),
     (46, 'Вок из углеродистой стали', 'Товары для дома', 'Вок из углеродистой стали предназначен для приготовления пищи. В нём можно обжаривать и перемешивать нарезанные ингредиенты. Правила ухода за стальной поверхностью следует уточнить перед использованием.', 299900, 7, 40, ARRAY['/media/dummyjson-products/52/1.webp']::text[]),
     (47, 'Разделочная доска', 'Товары для дома', 'Разделочная доска служит поверхностью для нарезки продуктов. На ней можно подготовить овощи или другие ингредиенты для блюда. После работы доску следует тщательно вымыть.', 129900, 8, 14, ARRAY['/media/dummyjson-products/53/1.webp']::text[]),
     (48, 'Жёлтая соковыжималка для цитрусовых', 'Товары для дома', 'Жёлтая соковыжималка предназначена для цитрусовых. С её помощью можно выжать сок из разрезанного плода. Свежий сок используют в напитках, соусах и заправках.', 89900, 12, 22, ARRAY['/media/dummyjson-products/54/1.webp']::text[]),
     (49, 'Яйцерезка', 'Товары для дома', 'Яйцерезка помогает нарезать сваренные яйца. Ломтики можно добавить в салат или использовать для бутербродов. Перед нарезкой яйцо необходимо очистить от скорлупы.', 69900, 15, 40, ARRAY['/media/dummyjson-products/55/1.webp']::text[]),
     (50, 'Раковина для ванной с деревянным оформлением и зеркалом', 'Мебель', 'Комплект для ванной включает раковину с деревянным оформлением и зеркало. Его можно использовать для обустройства зоны умывания. Перед установкой необходимо проверить размеры и требования к подключению.', 7999900, 9, 7, ARRAY['/media/dummyjson-products/15/1.webp', '/media/dummyjson-products/15/2.webp', '/media/dummyjson-products/15/3.webp']::text[]),
     (51, 'Ситечко с мелкой сеткой', 'Товары для дома', 'Ситечко с мелкой сеткой используют для процеживания. Оно помогает отделить небольшие частицы от жидкости. После использования сетку следует тщательно промыть.', 99900, 4, 85, ARRAY['/media/dummyjson-products/57/1.webp']::text[]),
     (52, 'Вилка', 'Товары для дома', 'Вилка предназначена для приёма пищи. Её можно использовать при повседневной сервировке или за общим столом. После еды столовый прибор необходимо вымыть.', 39900, 8, 7, ARRAY['/media/dummyjson-products/58/1.webp']::text[]),
     (53, 'Стакан', 'Товары для дома', 'Стакан предназначен для подачи напитков. Его можно поставить на стол во время еды или использовать отдельно. Допустимые температуры напитков и способ мытья следует уточнить для изделия.', 49900, 8, 46, ARRAY['/media/dummyjson-products/59/1.webp']::text[]),
     (54, 'Чёрная тёрка', 'Товары для дома', 'Чёрная тёрка предназначена для измельчения продуктов. С её помощью можно подготовить овощи или сыр для блюда. При работе с режущей поверхностью следует соблюдать осторожность.', 109900, 4, 84, ARRAY['/media/dummyjson-products/60/1.webp']::text[]),
     (55, 'Мороженое', 'Продукты питания', 'Мороженое подают как холодный десерт. Его можно есть отдельно или дополнить фруктами. Хранить продукт следует в замороженном виде согласно упаковке.', 54900, 9, 27, ARRAY['/media/dummyjson-products/28/1.webp', '/media/dummyjson-products/28/2.webp', '/media/dummyjson-products/28/3.webp', '/media/dummyjson-products/28/4.webp']::text[]),
     (56, 'Ручной блендер', 'Товары для дома', 'Ручной блендер используют для измельчения и смешивания ингредиентов. Он пригодится при приготовлении супов-пюре и соусов. Перед использованием следует ознакомиться с инструкцией к прибору.', 349900, 17, 84, ARRAY['/media/dummyjson-products/61/1.webp']::text[]),
     (57, 'Форма для льда', 'Товары для дома', 'Форма предназначена для замораживания кубиков льда. В ячейки наливают воду и помещают форму в морозильную камеру. Готовый лёд можно добавить в напитки.', 59900, 1, 13, ARRAY['/media/dummyjson-products/62/1.webp']::text[]),
     (58, 'Кухонное сито', 'Товары для дома', 'Кухонное сито помогает просеивать сыпучие продукты. Его можно использовать при подготовке муки для выпечки. Также через сито удобно отделять жидкость от частиц пищи.', 79900, 19, 68, ARRAY['/media/dummyjson-products/63/1.webp']::text[]),
     (59, 'Нож', 'Товары для дома', 'Кухонный нож используют для нарезки продуктов. Он пригодится при подготовке ингредиентов к приготовлению. Обращаться с лезвием и хранить нож следует осторожно.', 149900, 19, 7, ARRAY['/media/dummyjson-products/64/1.webp']::text[]),
     (60, 'Декоративные качели', 'Товары для дома', 'Декоративные качели предназначены для оформления пространства. Их можно включить в композицию интерьера или сада. Способ размещения и допустимую нагрузку необходимо уточнить у продавца.', 599900, 10, 47, ARRAY['/media/dummyjson-products/43/1.webp', '/media/dummyjson-products/43/2.webp', '/media/dummyjson-products/43/3.webp']::text[]),
     (61, 'Ланч-бокс', 'Товары для дома', 'Ланч-бокс предназначен для хранения и переноски еды. В него можно положить подготовленный обед для работы или учёбы. Возможность разогрева и правила мытья следует уточнить для контейнера.', 129900, 10, 94, ARRAY['/media/dummyjson-products/65/1.webp']::text[]),
     (62, 'Подставка-дерево для кружек', 'Товары для дома', 'Подставка-дерево предназначена для размещения кружек. Кружки располагают на её держателях, освобождая место на столе. Так посуда остаётся под рукой при приготовлении напитков.', 159900, 9, 88, ARRAY['/media/dummyjson-products/67/1.webp', '/media/dummyjson-products/67/2.webp']::text[]),
     (63, 'Сковорода', 'Товары для дома', 'Сковорода предназначена для приготовления блюд на плите. В ней можно обжаривать ингредиенты или готовить их вместе. Совместимость с типом плиты и правила ухода следует проверить перед покупкой.', 249900, 3, 90, ARRAY['/media/dummyjson-products/68/1.webp']::text[]),
     (64, 'Тарелка', 'Товары для дома', 'Тарелка предназначена для подачи еды к столу. Её можно использовать для отдельных порций. Условия мытья и возможность нагрева следует уточнить для изделия.', 39900, 7, 66, ARRAY['/media/dummyjson-products/69/1.webp']::text[]),
     (65, 'Декоративное растение для дома', 'Товары для дома', 'Декоративное растение House Showpiece Plant предназначено для оформления интерьера. Его можно разместить как акцент в комнате. Размер и особенности ухода стоит уточнить перед покупкой.', 399900, 7, 28, ARRAY['/media/dummyjson-products/45/1.webp', '/media/dummyjson-products/45/2.webp', '/media/dummyjson-products/45/3.webp']::text[]),
     (66, 'Красные щипцы', 'Товары для дома', 'Красные кухонные щипцы помогают брать и перекладывать продукты. Их можно использовать во время приготовления или сервировки. После контакта с пищей щипцы необходимо вымыть.', 69900, 15, 82, ARRAY['/media/dummyjson-products/70/1.webp']::text[]),
     (67, 'Серебристая кастрюля со стеклянной крышкой', 'Товары для дома', 'Кастрюля серебристого цвета дополнена стеклянной крышкой. В ней можно готовить супы и другие блюда. Перед использованием следует проверить совместимость посуды с плитой.', 399900, 6, 40, ARRAY['/media/dummyjson-products/71/1.webp']::text[]),
     (68, 'Лопатка с прорезями', 'Товары для дома', 'Лопатка с прорезями предназначена для переворачивания и перекладывания еды. Через отверстия может стекать лишняя жидкость. Утварь пригодится при приготовлении блюд на сковороде.', 89900, 13, 88, ARRAY['/media/dummyjson-products/72/1.webp']::text[]),
     (69, 'Подставка для специй', 'Товары для дома', 'Подставка для специй помогает собрать приправы в одном месте. Её можно разместить на кухне рядом с зоной приготовления. Размеры ёмкостей и их наличие в комплекте следует уточнить.', 199900, 12, 79, ARRAY['/media/dummyjson-products/73/1.webp']::text[]),
     (70, 'Цветочный горшок', 'Товары для дома', 'Цветочный горшок предназначен для размещения растения. Его можно использовать при оформлении комнаты или другой подходящей зоны. Перед посадкой стоит проверить размер горшка и наличие дренажа.', 149900, 7, 59, ARRAY['/media/dummyjson-products/46/1.webp', '/media/dummyjson-products/46/2.webp', '/media/dummyjson-products/46/3.webp', '/media/dummyjson-products/46/4.webp']::text[]),
     (71, 'Ложка', 'Товары для дома', 'Ложка предназначена для еды и сервировки. Ею удобно есть блюда, которые подают с жидкостью. После использования столовый прибор следует вымыть.', 49900, 2, 59, ARRAY['/media/dummyjson-products/74/1.webp']::text[]),
     (72, 'Поднос', 'Товары для дома', 'Поднос используют для подачи и переноса посуды. На нём можно разместить чашки или тарелки. После использования поверхность подноса следует очистить.', 169900, 7, 71, ARRAY['/media/dummyjson-products/75/1.webp']::text[]),
     (73, 'Деревянная скалка', 'Товары для дома', 'Деревянная скалка предназначена для раскатывания теста. С её помощью готовят пласты для выпечки или пельменей. После работы скалку следует очистить от остатков муки и теста.', 119900, 10, 80, ARRAY['/media/dummyjson-products/76/1.webp']::text[]),
     (74, 'Жёлтая овощечистка', 'Товары для дома', 'Жёлтая овощечистка помогает снимать кожуру с овощей и фруктов. Её можно использовать при подготовке продуктов к приготовлению. При очистке и мытье лезвия следует соблюдать осторожность.', 59900, 12, 35, ARRAY['/media/dummyjson-products/77/1.webp']::text[]),
     (75, 'Блендер в коробке', 'Товары для дома', 'Блендер в коробке предназначен для смешивания и измельчения продуктов. Его можно использовать для приготовления напитков или пюре. Комплектацию и правила эксплуатации следует проверить по инструкции.', 399900, 7, 9, ARRAY['/media/dummyjson-products/51/1.webp', '/media/dummyjson-products/51/2.webp', '/media/dummyjson-products/51/3.webp', '/media/dummyjson-products/51/4.webp']::text[]),
     (76, 'Amazon Echo Plus', 'Аксессуары', 'Amazon Echo Plus — умная колонка для дома. Она воспроизводит звук и поддерживает голосовое управление. Доступность голосовых функций зависит от региона и настроек сервиса.', 999900, 12, 61, ARRAY['/media/dummyjson-products/99/1.webp', '/media/dummyjson-products/99/2.webp']::text[]),
     (77, 'Apple AirPods Max, серебристые', 'Аксессуары', 'Apple AirPods Max Silver — накладные беспроводные наушники серебристого цвета. Они предназначены для прослушивания музыки и другого аудио. Совместимость и возможности подключения стоит проверить для своего устройства.', 5499900, 14, 59, ARRAY['/media/dummyjson-products/101/1.webp']::text[]),
     (78, 'Беспроводное зарядное устройство Apple Airpower', 'Аксессуары', 'Apple AirPower — зарядное устройство для беспроводной зарядки. Оно предназначено для размещения совместимых устройств на зарядной поверхности. Перед покупкой необходимо проверить совместимость и доступность конкретного изделия.', 799900, 4, 1, ARRAY['/media/dummyjson-products/102/1.webp']::text[]),
     (79, 'Apple HomePod Mini, космический серый', 'Аксессуары', 'Apple HomePod Mini Cosmic Grey — умная колонка серого цвета. Она предназначена для воспроизведения аудио и голосового управления. Для настройки и использования отдельных функций могут потребоваться совместимые устройства и сервисы Apple.', 999900, 18, 27, ARRAY['/media/dummyjson-products/103/1.webp']::text[]),
     (80, 'Электрическая плита', 'Товары для дома', 'Электрическая плита предназначена для приготовления пищи с помощью нагревательной поверхности. На ней можно использовать подходящую посуду. Перед подключением следует проверить требования к электропитанию.', 499900, 14, 21, ARRAY['/media/dummyjson-products/56/1.webp', '/media/dummyjson-products/56/2.webp', '/media/dummyjson-products/56/3.webp', '/media/dummyjson-products/56/4.webp']::text[]),
     (81, 'Зарядное устройство для Apple iPhone', 'Аксессуары', 'Зарядное устройство Apple предназначено для зарядки iPhone. Его используют вместе с подходящим кабелем и источником питания. Перед покупкой следует проверить разъёмы и комплектацию.', 199900, 19, 31, ARRAY['/media/dummyjson-products/104/1.webp', '/media/dummyjson-products/104/2.webp']::text[]),
     (82, 'Apple MagSafe Battery Pack', 'Аксессуары', 'Apple MagSafe Battery Pack — внешний аккумулятор для совместимого iPhone. Он крепится к телефону с помощью MagSafe и обеспечивает дополнительную зарядку. Совместимость с моделью телефона следует проверить заранее.', 999900, 17, 1, ARRAY['/media/dummyjson-products/105/1.webp', '/media/dummyjson-products/105/2.webp']::text[]),
     (83, 'Беспроводные наушники Beats Flex', 'Аксессуары', 'Beats Flex — беспроводные наушники для прослушивания аудио. Их можно подключать к совместимому устройству без аудиокабеля. Наушники подходят для музыки и разговоров.', 499900, 6, 50, ARRAY['/media/dummyjson-products/107/1.webp']::text[]),
     (84, 'Монопод', 'Аксессуары', 'Монопод служит опорой для съёмочного устройства. Он помогает удерживать камеру при съёмке. Перед покупкой стоит проверить тип крепления и допустимую нагрузку.', 199900, 9, 48, ARRAY['/media/dummyjson-products/109/1.webp', '/media/dummyjson-products/109/2.webp']::text[]),
     (85, 'Микроволновая печь', 'Товары для дома', 'Микроволновая печь предназначена для разогрева и приготовления пищи. В неё помещают еду в посуде, подходящей для микроволновых печей. Перед использованием следует ознакомиться с режимами и инструкцией прибора.', 899900, 12, 59, ARRAY['/media/dummyjson-products/66/1.webp', '/media/dummyjson-products/66/2.webp', '/media/dummyjson-products/66/3.webp', '/media/dummyjson-products/66/4.webp']::text[]),
     (86, 'Лампа для селфи с iPhone', 'Аксессуары', 'Лампа для селфи используется для освещения при съёмке на iPhone. Она помогает направить дополнительный свет на объект съёмки. Перед заказом стоит уточнить способ крепления и питания.', 149900, 19, 58, ARRAY['/media/dummyjson-products/110/1.webp']::text[]),
     (87, 'Монопод для селфи', 'Аксессуары', 'Монопод для селфи помогает расположить телефон дальше от пользователя. Это позволяет включить в кадр больше окружающего пространства. Совместимость крепления со смартфоном следует проверить заранее.', 129900, 19, 11, ARRAY['/media/dummyjson-products/111/1.webp']::text[]),
     (88, 'Студийный пьедестал для телевизионной камеры', 'Аксессуары', 'Студийный пьедестал предназначен для установки телевизионной камеры. Он служит опорой при работе в студии. Перед выбором необходимо проверить совместимость крепления и допустимую массу камеры.', 4999900, 8, 15, ARRAY['/media/dummyjson-products/112/1.webp']::text[]),
     (89, 'Мяч для американского футбола', 'Аксессуары', 'Мяч предназначен для американского футбола. Его используют для передач и тренировок владения мячом. Размер следует выбирать с учётом возраста и формата игры.', 199900, 5, 53, ARRAY['/media/dummyjson-products/137/1.webp']::text[]),
     (90, 'Apple MacBook Pro 14 дюймов, космический серый', 'Техника', 'Apple MacBook Pro — ноутбук с экраном диагональю 14 дюймов в цвете Space Grey. Он предназначен для работы с приложениями, документами и мультимедиа. Конфигурацию памяти и другие параметры конкретного экземпляра следует уточнить.', 19999900, 5, 24, ARRAY['/media/dummyjson-products/78/1.webp', '/media/dummyjson-products/78/2.webp', '/media/dummyjson-products/78/3.webp']::text[]),
     (91, 'Бейсбольный мяч', 'Аксессуары', 'Бейсбольный мяч используют для игры и тренировок. Его бросают, ловят перчаткой и отбивают битой. При занятиях следует выбирать подходящую площадку и защитное снаряжение.', 89900, 2, 100, ARRAY['/media/dummyjson-products/138/1.webp']::text[]),
     (92, 'Баскетбольный мяч', 'Аксессуары', 'Баскетбольный мяч предназначен для игры на площадке. Его используют для ведения, передач и бросков в кольцо. Размер мяча выбирают в зависимости от возраста и правил игры.', 149900, 7, 75, ARRAY['/media/dummyjson-products/140/1.webp']::text[]),
     (93, 'Баскетбольное кольцо', 'Аксессуары', 'Баскетбольное кольцо является целью для бросков мяча. Его устанавливают на подходящем щите. Перед монтажом нужно проверить размеры и совместимость крепления.', 399900, 8, 43, ARRAY['/media/dummyjson-products/141/1.webp']::text[]),
     (94, 'Мяч для крикета', 'Аксессуары', 'Мяч для крикета используют при подаче и отбивании битой. Он предназначен для игры и тренировок по крикету. Для занятий важно подобрать подходящую защитную экипировку.', 129900, 9, 30, ARRAY['/media/dummyjson-products/142/1.webp']::text[]),
     (95, 'Ноутбук Asus Zenbook Pro с двумя экранами', 'Техника', 'Asus Zenbook Pro — ноутбук с двумя экранами. Дополнительный экран можно использовать для размещения окон и рабочих инструментов. Конфигурацию устройства следует уточнить перед покупкой.', 17999900, 11, 45, ARRAY['/media/dummyjson-products/79/1.webp', '/media/dummyjson-products/79/2.webp', '/media/dummyjson-products/79/3.webp']::text[]),
     (96, 'Бита для крикета', 'Аксессуары', 'Бита для крикета предназначена для отбивания мяча. Её используют во время игры и тренировок. Размер биты подбирают с учётом роста и предпочтений игрока.', 299900, 3, 98, ARRAY['/media/dummyjson-products/143/1.webp']::text[]),
     (97, 'Калитка для крикета', 'Аксессуары', 'Калитка для крикета используется на игровой площадке как цель для подачи. Игрок с битой защищает её от мяча. Состав комплекта и способ установки следует уточнить перед покупкой.', 299900, 17, 25, ARRAY['/media/dummyjson-products/145/1.webp']::text[]),
     (98, 'Перьевой волан', 'Аксессуары', 'Перьевой волан предназначен для бадминтона. Игроки перебивают его ракетками через сетку. Перьевое оперение влияет на полёт волана.', 59900, 3, 95, ARRAY['/media/dummyjson-products/146/1.webp']::text[]),
     (99, 'Футбольный мяч', 'Аксессуары', 'Футбольный мяч используют для игры ногами и тренировок на поле. Он подходит для отработки передач и ударов. Размер мяча следует выбирать с учётом возраста игроков.', 179900, 5, 96, ARRAY['/media/dummyjson-products/147/1.webp']::text[]),
     (100, 'Huawei Matebook X Pro', 'Техника', 'Huawei MateBook X Pro — ноутбук для работы и повседневных задач. На нём можно пользоваться приложениями, браузером и документами. Характеристики конкретной конфигурации следует уточнить перед заказом.', 13999900, 9, 75, ARRAY['/media/dummyjson-products/80/1.webp', '/media/dummyjson-products/80/2.webp', '/media/dummyjson-products/80/3.webp']::text[]),
     (101, 'Мяч для гольфа', 'Аксессуары', 'Мяч для гольфа предназначен для ударов клюшкой на поле. Его используют во время игры и тренировок. В гольфе задача игрока — направить мяч в лунку.', 99900, 17, 84, ARRAY['/media/dummyjson-products/148/1.webp']::text[]),
     (102, 'Клюшка для гольфа типа айрон', 'Аксессуары', 'Iron Golf — клюшка типа айрон для игры в гольф. Ею выполняют удары по мячу с разных дистанций. Подходящий номер и параметры клюшки следует уточнить перед выбором.', 499900, 7, 90, ARRAY['/media/dummyjson-products/149/1.webp']::text[]),
     (103, 'Металлическая бейсбольная бита', 'Аксессуары', 'Металлическая бейсбольная бита предназначена для отбивания мяча. Её используют на тренировках и во время игры. Длину и вес биты подбирают под игрока и правила соревнований.', 299900, 20, 16, ARRAY['/media/dummyjson-products/150/1.webp']::text[]),
     (104, 'Lenovo Yoga 920', 'Техника', 'Lenovo Yoga 920 — ноутбук-трансформер. Его экран можно поворачивать для разных способов работы с устройством. Перед покупкой стоит уточнить конфигурацию и состояние экземпляра.', 10999900, 7, 40, ARRAY['/media/dummyjson-products/81/1.webp', '/media/dummyjson-products/81/2.webp', '/media/dummyjson-products/81/3.webp']::text[]),
     (105, 'Новый ноутбук DELL XPS 13 9300', 'Техника', 'Dell XPS 13 9300 — ноутбук для работы с документами и приложениями. Его можно использовать дома или брать с собой. Объём памяти и другие параметры зависят от конфигурации.', 14999900, 12, 74, ARRAY['/media/dummyjson-products/82/1.webp', '/media/dummyjson-products/82/2.webp', '/media/dummyjson-products/82/3.webp']::text[]),
     (106, 'Рубашка в синюю и чёрную клетку', 'Одежда', 'Рубашка в синюю и чёрную клетку подходит для повседневного гардероба. Её можно сочетать с джинсами или однотонными брюками. Для выбора посадки стоит сверить размеры.', 299900, 15, 38, ARRAY['/media/dummyjson-products/83/1.webp', '/media/dummyjson-products/83/2.webp', '/media/dummyjson-products/83/3.webp', '/media/dummyjson-products/83/4.webp']::text[]),
     (107, 'Мужская футболка Gigabyte Aorus', 'Одежда', 'Мужская футболка Gigabyte Aorus дополняет повседневный гардероб. Её можно носить с джинсами или брюками. Размер и состав ткани следует уточнить в карточке товара.', 249900, 1, 90, ARRAY['/media/dummyjson-products/84/1.webp', '/media/dummyjson-products/84/2.webp', '/media/dummyjson-products/84/3.webp', '/media/dummyjson-products/84/4.webp']::text[]),
     (108, 'Мужская рубашка в шотландскую клетку', 'Одежда', 'Мужская рубашка в клетку подходит для повседневных комплектов. Её можно носить самостоятельно или поверх футболки. Перед заказом стоит сверить размер и рекомендации по уходу.', 349900, 20, 82, ARRAY['/media/dummyjson-products/85/1.webp', '/media/dummyjson-products/85/2.webp', '/media/dummyjson-products/85/3.webp', '/media/dummyjson-products/85/4.webp']::text[]),
     (109, 'Мужская рубашка с коротким рукавом', 'Одежда', 'Мужская рубашка с короткими рукавами предназначена для повседневной носки. Её можно сочетать с брюками или шортами. Размер и состав материала следует проверить перед заказом.', 199900, 7, 2, ARRAY['/media/dummyjson-products/86/1.webp', '/media/dummyjson-products/86/2.webp', '/media/dummyjson-products/86/3.webp', '/media/dummyjson-products/86/4.webp']::text[]),
     (110, 'Мужская рубашка в клетку', 'Одежда', 'Мужская клетчатая рубашка дополняет повседневный образ. Её рисунок можно сочетать с однотонными вещами. Для подходящей посадки проверьте размерную сетку.', 279900, 11, 95, ARRAY['/media/dummyjson-products/87/1.webp', '/media/dummyjson-products/87/2.webp', '/media/dummyjson-products/87/3.webp', '/media/dummyjson-products/87/4.webp']::text[]),
     (111, 'Nike Air Jordan 1, красно-чёрные', 'Одежда', 'Nike Air Jordan 1 — кроссовки в красно-чёрной расцветке. Они дополняют спортивный или повседневный комплект. Перед покупкой стоит сверить размер обуви.', 1499900, 4, 7, ARRAY['/media/dummyjson-products/88/1.webp', '/media/dummyjson-products/88/2.webp', '/media/dummyjson-products/88/3.webp', '/media/dummyjson-products/88/4.webp']::text[]),
     (112, 'Бейсбольные бутсы Nike', 'Одежда', 'Nike Baseball Cleats — обувь для бейсбола. Шипованная подошва предназначена для сцепления с игровой поверхностью. Перед выбором проверьте размер и пригодность шипов для своей площадки.', 799900, 18, 12, ARRAY['/media/dummyjson-products/89/1.webp', '/media/dummyjson-products/89/2.webp', '/media/dummyjson-products/89/3.webp', '/media/dummyjson-products/89/4.webp']::text[]),
     (113, 'Кроссовки Puma Future Rider', 'Одежда', 'Puma Future Rider — кроссовки для повседневной носки. Их можно сочетать со спортивной одеждой или джинсами. Размер следует выбирать по размерной сетке производителя.', 899900, 4, 90, ARRAY['/media/dummyjson-products/90/1.webp', '/media/dummyjson-products/90/2.webp', '/media/dummyjson-products/90/3.webp', '/media/dummyjson-products/90/4.webp']::text[]),
     (114, 'Спортивные кроссовки молочного и красного цветов', 'Одежда', 'Спортивные кроссовки выполнены в сочетании молочного и красного цветов. Их можно носить со спортивной или повседневной одеждой. При выборе важно сверить размер и посадку.', 1199900, 5, 17, ARRAY['/media/dummyjson-products/91/1.webp', '/media/dummyjson-products/91/2.webp', '/media/dummyjson-products/91/3.webp', '/media/dummyjson-products/91/4.webp']::text[]),
     (115, 'Кроссовки в молочно-красной расцветке', 'Одежда', 'Кроссовки в молочно-красной расцветке подходят для повседневных образов. Спортивный силуэт можно сочетать с брюками или джинсами. Перед заказом проверьте размер обуви и фотографии модели.', 1099900, 0, 62, ARRAY['/media/dummyjson-products/92/1.webp', '/media/dummyjson-products/92/2.webp', '/media/dummyjson-products/92/4.webp']::text[]),
     (116, 'Часы с коричневым кожаным ремешком', 'Аксессуары', 'Наручные часы дополнены коричневым кожаным ремешком. Они показывают время и служат аксессуаром к повседневному образу. Размер ремешка и характеристики механизма следует уточнить перед покупкой.', 899900, 6, 32, ARRAY['/media/dummyjson-products/93/1.webp', '/media/dummyjson-products/93/2.webp', '/media/dummyjson-products/93/3.webp']::text[]),
     (117, 'Longines Master Collection', 'Аксессуары', 'Longines Master Collection — коллекция наручных часов. Часы предназначены для отображения времени и дополняют классический образ. Особенности циферблата и механизма следует проверить для конкретной модели.', 14999900, 17, 100, ARRAY['/media/dummyjson-products/94/1.webp', '/media/dummyjson-products/94/2.webp', '/media/dummyjson-products/94/3.webp']::text[]),
     (118, 'Rolex Cellini Date с чёрным циферблатом', 'Аксессуары', 'Rolex Cellini Date — наручные часы с чёрным циферблатом. Модель показывает время и дату. Перед покупкой стоит уточнить характеристики и состояние конкретного экземпляра.', 89999900, 9, 40, ARRAY['/media/dummyjson-products/95/1.webp', '/media/dummyjson-products/95/2.webp', '/media/dummyjson-products/95/3.webp']::text[]),
     (119, 'Rolex Cellini Moonphase', 'Аксессуары', 'Rolex Cellini Moonphase — наручные часы с указателем фаз Луны. Помимо времени на циферблате отображается лунный цикл. Характеристики и состояние конкретного экземпляра следует уточнить у продавца.', 129999900, 18, 36, ARRAY['/media/dummyjson-products/96/1.webp', '/media/dummyjson-products/96/2.webp', '/media/dummyjson-products/96/3.webp']::text[]),
     (120, 'Rolex Datejust', 'Аксессуары', 'Rolex Datejust — наручные часы с отображением даты. Они предназначены для повседневного отслеживания времени. Исполнение циферблата и характеристики конкретной модели стоит уточнить перед покупкой.', 109999900, 4, 86, ARRAY['/media/dummyjson-products/97/1.webp', '/media/dummyjson-products/97/2.webp', '/media/dummyjson-products/97/3.webp']::text[]),
     (121, 'Часы Rolex Submariner', 'Аксессуары', 'Rolex Submariner — наручные часы из линейки для дайвинга. Они показывают время и могут использоваться как повседневный аксессуар. Водозащиту конкретного экземпляра следует проверить с учётом его состояния.', 139999900, 5, 55, ARRAY['/media/dummyjson-products/98/1.webp', '/media/dummyjson-products/98/2.webp', '/media/dummyjson-products/98/3.webp']::text[]),
     (122, 'Apple Airpods', 'Аксессуары', 'Apple AirPods — беспроводные наушники для прослушивания аудио. Они также могут использоваться для разговоров с подключённым устройством. Поколение и совместимость следует уточнить перед покупкой.', 1299900, 16, 67, ARRAY['/media/dummyjson-products/100/1.webp', '/media/dummyjson-products/100/2.webp', '/media/dummyjson-products/100/3.webp']::text[]),
     (123, 'Apple Watch Series 4, золотистые', 'Аксессуары', 'Apple Watch Series 4 Gold — умные часы золотистого цвета. Они показывают время и работают с приложениями на совместимом iPhone. Доступные функции зависят от версии программного обеспечения и региона.', 3499900, 12, 33, ARRAY['/media/dummyjson-products/106/1.webp', '/media/dummyjson-products/106/2.webp', '/media/dummyjson-products/106/3.webp']::text[]),
     (124, 'Силиконовый чехол для iPhone 12 с MagSafe, сливовый', 'Аксессуары', 'Силиконовый чехол сливового цвета предназначен для iPhone 12. Он закрывает корпус телефона и поддерживает MagSafe. Перед покупкой стоит проверить совместимость с конкретной моделью iPhone.', 299900, 14, 69, ARRAY['/media/dummyjson-products/108/1.webp', '/media/dummyjson-products/108/2.webp', '/media/dummyjson-products/108/3.webp', '/media/dummyjson-products/108/4.webp']::text[]),
     (125, 'Мотоцикл без указанной марки', 'Техника', 'Generic Motorcycle — мотоцикл для передвижения по дороге. Для управления необходимы соответствующая подготовка и документы. Техническое состояние и характеристики экземпляра следует уточнить у продавца.', 39999900, 12, 34, ARRAY['/media/dummyjson-products/113/1.webp', '/media/dummyjson-products/113/2.webp', '/media/dummyjson-products/113/3.webp', '/media/dummyjson-products/113/4.webp']::text[]),
     (126, 'Kawasaki Z800', 'Техника', 'Kawasaki Z800 — дорожный мотоцикл. Он предназначен для поездок с управлением водителем на двух колёсах. Перед покупкой следует проверить документы, состояние и характеристики экземпляра.', 89999900, 10, 52, ARRAY['/media/dummyjson-products/114/1.webp', '/media/dummyjson-products/114/2.webp', '/media/dummyjson-products/114/3.webp', '/media/dummyjson-products/114/4.webp']::text[]),
     (127, 'MotoGP CI.H1', 'Техника', 'MotoGP CI.H1 — мотоцикл спортивного направления. Он относится к технике для поездок на двух колёсах. Условия использования и характеристики конкретного экземпляра необходимо уточнить у продавца.', 149999900, 7, 10, ARRAY['/media/dummyjson-products/115/1.webp', '/media/dummyjson-products/115/2.webp', '/media/dummyjson-products/115/3.webp', '/media/dummyjson-products/115/4.webp']::text[]),
     (128, 'Мотороллер', 'Техника', 'Scooter Motorcycle — мотороллер для передвижения. Его используют для поездок по дорогам при соблюдении действующих правил. Перед покупкой нужно проверить документы и техническое состояние.', 29999900, 6, 84, ARRAY['/media/dummyjson-products/116/1.webp', '/media/dummyjson-products/116/2.webp', '/media/dummyjson-products/116/3.webp', '/media/dummyjson-products/116/4.webp']::text[]),
     (129, 'Спортивный мотоцикл', 'Техника', 'Sportbike Motorcycle — мотоцикл спортивного типа. Его конструкция ориентирована на управление в посадке спортивного мотоцикла. Технические параметры и состояние следует уточнить до покупки.', 74999900, 12, 0, ARRAY['/media/dummyjson-products/117/1.webp', '/media/dummyjson-products/117/2.webp', '/media/dummyjson-products/117/3.webp', '/media/dummyjson-products/117/4.webp']::text[]),
     (130, 'Мыло для рук Attitude Super Leaves', 'Косметика', 'Мыло Attitude Super Leaves предназначено для мытья рук. Его наносят на влажную кожу и смывают водой. Состав средства можно проверить на упаковке.', 89900, 18, 94, ARRAY['/media/dummyjson-products/118/1.webp', '/media/dummyjson-products/118/2.webp', '/media/dummyjson-products/118/3.webp']::text[]),
     (131, 'Средство для мытья тела Olay Ultra Moisture с маслом ши', 'Косметика', 'Olay Ultra Moisture — средство для мытья тела с маслом ши. Его используют во время душа и затем смывают водой. Состав и рекомендации по применению указаны на упаковке.', 129900, 16, 34, ARRAY['/media/dummyjson-products/119/1.webp', '/media/dummyjson-products/119/2.webp', '/media/dummyjson-products/119/3.webp']::text[]),
     (132, 'Мужской лосьон для тела и лица Vaseline', 'Косметика', 'Vaseline Men — лосьон для ухода за кожей лица и тела. Его наносят на кожу для увлажнения. Перед использованием стоит ознакомиться с составом и указаниями на упаковке.', 99900, 13, 95, ARRAY['/media/dummyjson-products/120/1.webp', '/media/dummyjson-products/120/2.webp', '/media/dummyjson-products/120/3.webp']::text[]),
     (133, 'iPhone 5s', 'Техника', 'iPhone 5s — смартфон Apple для звонков, сообщений и приложений. Он относится к более раннему поколению iPhone. Перед покупкой стоит проверить состояние и совместимость нужных приложений.', 1999900, 13, 25, ARRAY['/media/dummyjson-products/121/1.webp', '/media/dummyjson-products/121/2.webp', '/media/dummyjson-products/121/3.webp']::text[]),
     (134, 'iPhone 6', 'Техника', 'iPhone 6 — смартфон Apple для связи и повседневных задач. На нём можно пользоваться камерой и поддерживаемыми приложениями. Версию системы и состояние устройства следует уточнить у продавца.', 2999900, 7, 60, ARRAY['/media/dummyjson-products/122/1.webp', '/media/dummyjson-products/122/2.webp', '/media/dummyjson-products/122/3.webp']::text[]),
     (135, 'iPhone 13 Pro', 'Техника', 'iPhone 13 Pro — смартфон Apple из линейки Pro. Он предназначен для связи, съёмки фото и видео и работы с приложениями. Объём памяти и состояние конкретного устройства следует проверить перед покупкой.', 10999900, 9, 56, ARRAY['/media/dummyjson-products/123/1.webp', '/media/dummyjson-products/123/2.webp', '/media/dummyjson-products/123/3.webp']::text[]),
     (136, 'iPhone X', 'Техника', 'iPhone X — смартфон Apple с сенсорным экраном. Его используют для звонков, съёмки и работы с приложениями. Перед заказом стоит уточнить состояние аккумулятора и объём памяти.', 8999900, 20, 37, ARRAY['/media/dummyjson-products/124/1.webp', '/media/dummyjson-products/124/2.webp', '/media/dummyjson-products/124/3.webp']::text[]),
     (137, 'Oppo A57', 'Техника', 'Oppo A57 — смартфон для звонков и работы с приложениями. Камера позволяет снимать фотографии и видео. Конфигурацию и состояние устройства следует уточнить перед покупкой.', 2499900, 2, 19, ARRAY['/media/dummyjson-products/125/1.webp', '/media/dummyjson-products/125/2.webp', '/media/dummyjson-products/125/3.webp']::text[]),
     (138, 'Oppo F19 Pro Plus', 'Техника', 'Oppo F19 Pro Plus — смартфон для связи и мультимедиа. Его можно использовать для просмотра содержимого и фотосъёмки. Объём памяти и характеристики конкретной версии стоит проверить у продавца.', 3999900, 19, 78, ARRAY['/media/dummyjson-products/126/1.webp', '/media/dummyjson-products/126/2.webp', '/media/dummyjson-products/126/3.webp']::text[]),
     (139, 'Oppo K1', 'Техника', 'Oppo K1 — смартфон для повседневной связи. На нём можно запускать приложения и пользоваться камерой. Перед заказом уточните конфигурацию и состояние экземпляра.', 2999900, 18, 55, ARRAY['/media/dummyjson-products/127/1.webp', '/media/dummyjson-products/127/2.webp', '/media/dummyjson-products/127/3.webp', '/media/dummyjson-products/127/4.webp']::text[]),
     (140, 'Realme C35', 'Техника', 'Realme C35 — смартфон для звонков, сообщений и интернет-сервисов. Он также предназначен для просмотра видео и фотосъёмки. Параметры памяти и комплектацию следует проверить перед покупкой.', 1499900, 15, 48, ARRAY['/media/dummyjson-products/128/1.webp', '/media/dummyjson-products/128/2.webp', '/media/dummyjson-products/128/3.webp']::text[]),
     (141, 'Realme X', 'Техника', 'Realme X — смартфон для связи и использования мобильных приложений. С его помощью можно снимать фото и просматривать видео. Состояние и конфигурацию конкретного устройства стоит уточнить.', 2999900, 7, 12, ARRAY['/media/dummyjson-products/129/1.webp', '/media/dummyjson-products/129/2.webp', '/media/dummyjson-products/129/3.webp']::text[]),
     (142, 'Realme XT', 'Техника', 'Realme XT — смартфон для повседневных задач и общения. Камера устройства используется для фото и видео. Перед выбором проверьте объём памяти и состояние телефона.', 3499900, 12, 80, ARRAY['/media/dummyjson-products/130/1.webp', '/media/dummyjson-products/130/2.webp', '/media/dummyjson-products/130/3.webp']::text[]),
     (143, 'Samsung Galaxy S7', 'Техника', 'Samsung Galaxy S7 — смартфон линейки Galaxy. Он предназначен для звонков, съёмки и работы с поддерживаемыми приложениями. Перед покупкой следует проверить состояние устройства и совместимость нужного ПО.', 2999900, 20, 67, ARRAY['/media/dummyjson-products/131/1.webp', '/media/dummyjson-products/131/2.webp', '/media/dummyjson-products/131/3.webp']::text[]),
     (144, 'Samsung Galaxy S8', 'Техника', 'Samsung Galaxy S8 — смартфон для общения и мультимедиа. Сенсорный экран используется для работы с приложениями и просмотра контента. Состояние дисплея и аккумулятора стоит уточнить у продавца.', 4999900, 19, 0, ARRAY['/media/dummyjson-products/132/1.webp', '/media/dummyjson-products/132/2.webp', '/media/dummyjson-products/132/3.webp']::text[]),
     (145, 'Samsung Galaxy S10', 'Техника', 'Samsung Galaxy S10 — смартфон линейки Galaxy S. Он подходит для связи, фотосъёмки и работы с приложениями. Конфигурацию памяти и состояние конкретного экземпляра следует проверить.', 6999900, 6, 19, ARRAY['/media/dummyjson-products/133/1.webp', '/media/dummyjson-products/133/2.webp', '/media/dummyjson-products/133/3.webp']::text[]),
     (146, 'Vivo S1', 'Техника', 'Vivo S1 — смартфон для звонков, сообщений и мобильных приложений. С его помощью можно снимать фотографии и смотреть видео. Перед покупкой уточните версию устройства и объём памяти.', 2499900, 10, 50, ARRAY['/media/dummyjson-products/134/1.webp', '/media/dummyjson-products/134/2.webp', '/media/dummyjson-products/134/3.webp']::text[]),
     (147, 'Vivo V9', 'Техника', 'Vivo V9 — смартфон для общения и повседневных цифровых задач. Его камера позволяет делать снимки и записывать видео. Состояние и характеристики конкретного экземпляра следует проверить у продавца.', 2999900, 18, 82, ARRAY['/media/dummyjson-products/135/1.webp', '/media/dummyjson-products/135/2.webp', '/media/dummyjson-products/135/3.webp']::text[]),
     (148, 'Vivo X21', 'Техника', 'Vivo X21 — смартфон для работы с приложениями и связи. На нём можно просматривать видео и пользоваться камерой. Перед заказом стоит уточнить комплектацию и состояние устройства.', 4999900, 17, 7, ARRAY['/media/dummyjson-products/136/1.webp', '/media/dummyjson-products/136/2.webp', '/media/dummyjson-products/136/3.webp']::text[]),
     (149, 'Бейсбольная перчатка', 'Аксессуары', 'Бейсбольная перчатка предназначена для ловли мяча. Её используют во время игры и тренировок. Размер и руку для ношения следует подобрать под игрока.', 249900, 3, 22, ARRAY['/media/dummyjson-products/139/1.webp', '/media/dummyjson-products/139/2.webp', '/media/dummyjson-products/139/3.webp']::text[]),
     (150, 'Шлем для крикета', 'Аксессуары', 'Шлем для крикета предназначен для защиты головы во время игры. Его используют вместе с другой подходящей защитной экипировкой. Размер и посадку необходимо проверить перед выходом на поле.', 449900, 10, 10, ARRAY['/media/dummyjson-products/144/1.webp', '/media/dummyjson-products/144/2.webp', '/media/dummyjson-products/144/3.webp', '/media/dummyjson-products/144/4.webp']::text[])
), inserted AS (
     INSERT INTO product (category_id, seller_id, price, discount, name, description, available_count, created_at, updated_at)
     SELECT category.id, u.id, catalog.price, catalog.discount, catalog.name, catalog.description, catalog.stock,
           '2026-09-02 12:00:00+00'::timestamptz + (catalog.seq - 1) * interval '9 hours',
           '2026-09-02 12:00:00+00'::timestamptz + (catalog.seq - 1) * interval '9 hours'
    FROM catalog
    JOIN category ON category.category = catalog.category
    JOIN "user" AS u ON u.email = 'seed.market-seller.' || lpad((((catalog.seq - 1) % 80) + 1)::text, 3, '0') || '@example.test'
    RETURNING id, name
)
INSERT INTO product_picture (product_id, picture_url)
SELECT inserted.id, picture.picture_url
FROM inserted
JOIN catalog ON catalog.name = inserted.name
CROSS JOIN LATERAL unnest(catalog.picture_urls) AS picture(picture_url);
